CREATE TABLE staff_accounts (id BIGINT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(80) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, role VARCHAR(40) NOT NULL, employee_id BIGINT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, CONSTRAINT fk_staff_employee FOREIGN KEY (employee_id) REFERENCES employees(id));
CREATE TABLE salary_slips (id BIGINT AUTO_INCREMENT PRIMARY KEY, employee_id BIGINT NOT NULL, salary_month CHAR(7) NOT NULL, basic DECIMAL(12,2) NOT NULL DEFAULT 0, allowances DECIMAL(12,2) NOT NULL DEFAULT 0, deductions DECIMAL(12,2) NOT NULL DEFAULT 0, net_pay DECIMAL(12,2) NOT NULL DEFAULT 0, payment_status VARCHAR(20) NOT NULL DEFAULT 'PENDING', credited_at DATETIME NULL, CONSTRAINT fk_salary_employee FOREIGN KEY(employee_id) REFERENCES employees(id), CONSTRAINT uk_salary_month UNIQUE(employee_id,salary_month));
CREATE TABLE leave_requests (id BIGINT AUTO_INCREMENT PRIMARY KEY, employee_id BIGINT NOT NULL, leave_type VARCHAR(30) NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, reason VARCHAR(500), status VARCHAR(20) NOT NULL DEFAULT 'PENDING', requested_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, reviewed_by VARCHAR(80), reviewed_at DATETIME, CONSTRAINT fk_leave_employee FOREIGN KEY(employee_id) REFERENCES employees(id));
